      'uniform float uNow,uAmt,uPulse,uBeat0,uGlyphOn,uMercyB; uniform vec2 uBase; uniform vec3 uA,uW,uP,uInk,uL0,uL1,uL2,uL3,uMark; uniform sampler2D uBands,uGlyph; varying vec2 vXZ;',
