      ca[3]=ML_TETH_RGB[0]; ca[4]=ML_TETH_RGB[1]; ca[5]=ML_TETH_RGB[2]; m.geometry.attributes.color.needsUpdate=true;   // THE PACKET'S OWN RAMP (wave 8.2, Y2b), written ONCE at acquire exactly as the pale-white one was: dim gold tail → full ML_GOLD head, so the thing travelling up the thread has a front and a back and the eye can tell which way it is going
